  patterns: [
    [/^You pull the cork\. \*(.*?)\* pours out in a flood of golden words and sweeps you up into it — and you live happily ever after as a minor character with exactly one line: "Look out! A dragon!" It is a good line\. You say it very well\. You say it every night, forever\.$/, "你拉起软木板。*$1* 倒出一股金字水，把你卷进其中—— 从此你作为一个小人物过着幸福的生活，完全有一句: “看好，一条龙!” 这句词很好，你说得非常好，你每晚都说，永远。"],
    [/^Thousands of bottles, each labelled in a tall, spidery hand\. \*(.{0,240}?)\.\* \*(.*?)\.\* Each one glows the colour of a hearth seen through a window on a cold night\.$/, (_, v1, v2) => "千瓶，每瓶贴在高大的蜘蛛手中。 *" + PureTVChinese.translate(v1) + "* *" + PureTVChinese.translate(v2) + ". * 每瓶都照亮着寒冷夜晚从窗户看见的灵车的颜色。"],
    [/^(.*?) \*Thank you for playing The Story Thief of Greymantle\. Luckily, this is the kind of book you can turn back a page in\.\*$/, "$1 * 谢谢你出演\"灰门贼的故事\" 幸运的是，这是你能够翻回一页的书。*"],
    [/^You take down a bottle at random\. The label reads: \*(.*?)\.\* It's warm, and it hums\.$/, (_, v1) => "标注是: *" + PureTVChinese.translate(v1) + ". * 温暖，哼哼。"],
    [/^Using the (.{0,240}?) on (.*?) achieves nothing, apart from a slight feeling of embarrassment\.$/, (_, v1, v2) => PureTVChinese.translate(v2) + "上使用" + PureTVChinese.translate(v1) + "号机除了略感尴尬外，没有实现任何目的。"],
    [/^You wave the (.{0,240}?) at (.*?)\. Nothing happens\. You put it away before anyone notices\.$/, (_, v1, v2) => "你挥动" + PureTVChinese.translate(v1) + "号，" + PureTVChinese.translate(v2) + "号，什么事都没有，你先把它收起来，再不通知别人"],
    [/^You try making conversation with (.*?)\. It's a short conversation\.$/, (_, v1) => "你试着和" + PureTVChinese.translate(v1) + "谈话，这是个简短的谈话。"],
    [/^You can't think of anything useful to do with (.*?)\.$/, "$1号，你根本想不出有什么有用的东西。"],
    [/^The (.{0,240}?) and (.*?) have nothing to say to one another\.$/, (_, v1, v2) => PureTVChinese.translate(v1) + "和" + PureTVChinese.translate(v2) + "号两条无话可说。"],
    [/^You can't see how the (.{0,240}?) and the (.*?) go together\.$/, (_, v1, v2) => "你看不出" + PureTVChinese.translate(v1) + "和" + PureTVChinese.translate(v2) + "之间有什么联系。"],
    [/^You can't think how the (.{0,240}?) would help with (.*?)\.$/, (_, v1, v2) => PureTVChinese.translate(v1) + "号怎么能帮助" + PureTVChinese.translate(v2) + "号"],
    [/^(.*?) times, each of them educational$/, "$1次，每一次都受过教育"],
    [/^Endings found: (.{0,240}?) of (.*?)$/, (_, v1, v2) => "已发现结局：" + PureTVChinese.translate(v1) + "／" + PureTVChinese.translate(v2)],
    [/^opacity (.*?)ms$/, (_, v1) => "透明度 " + PureTVChinese.translate(v1) + "毫秒"],
    [/^No scene (.*?)$/, (_, v1) => "没有场景" + PureTVChinese.translate(v1)],
    [/^\+(.*?) points$/, "＋$1 分"],
    [/^Walk to (.*?)$/, (_, v1) => "走向" + PureTVChinese.translate(v1)],
    [/^Use (.{0,240}?) on (.*?)$/, (_, v1, v2) => "对" + PureTVChinese.translate(v2) + "使用" + PureTVChinese.translate(v1)],
    [/^Talk to (.*?)$/, (_, v1) => "与" + PureTVChinese.translate(v1) + "交谈"],
    [/^Look at (.*?)$/, (_, v1) => "观察" + PureTVChinese.translate(v1)],
    [/^Using: (.*?)$/, (_, v1) => "正在使用：" + PureTVChinese.translate(v1)],
    [/^Sound: (.*?)$/, (_, v1) => "音效：" + PureTVChinese.translate(v1)],
    [/^toast (.*?)$/, (_, v1) => "吐司" + PureTVChinese.translate(v1) + "号"],
    [/^pages (.*?)$/, (_, v1) => "第" + PureTVChinese.translate(v1) + "页"],
    [/^Text: (.*?)$/, (_, v1) => "文字速度：" + PureTVChinese.translate(v1)],
    [/^It's (.*?)\.$/, (_, v1) => "这是" + PureTVChinese.translate(v1) + "。"],
    [/^Use (.*?)$/, (_, v1) => "使用" + PureTVChinese.translate(v1)],
    [/^Go (.*?)$/, (_, v1) => "前往" + PureTVChinese.translate(v1)],
    [/^\*"(.+)"\*$/, (_, question) => '*“' + PureTVChinese.translate(question) + '”*']
  ]
